from docx import Document
from pathlib import Path
path=Path('output/tsa-markup-redline.docx')
doc=Document(path)
old='; provided that this waiver shall not limit either Party\'s liability for third-party claims for which indemnification is provided under this Agreement, or for fraud, willful misconduct, confidentiality breaches, or IP infringement to the extent applicable.'
new='; provided that this waiver shall not limit either Party\'s liability with respect to third-party claims for which indemnification is provided under this Agreement, consistent with APA §7.12(d).'
count=0
for p in list(doc.paragraphs)+[p for t in doc.tables for row in t.rows for c in row.cells for p in c.paragraphs]:
    for r in p.runs:
        if old in r.text:
            r.text=r.text.replace(old,new); count+=1
if count != 1: raise SystemExit(f'replaced {count} occurrences')
doc.save(path)
print('updated', count)
PY","description":"Align damages waiver with APA carve-out"}

